import { Component, EventEmitter, Input, Output } from '@angular/core';
import { ColorSliderComponent } from '../color-slider/color-slider.component';
import { ColorPaletteComponent } from '../color-palette/color-palette.component';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-colorpicker',
  standalone: true,
  imports: [CommonModule, ColorSliderComponent, ColorPaletteComponent],
  templateUrl: './colorpicker.component.html',
  styleUrl: './colorpicker.component.scss'
})
export class ColorpickerComponent {

  public hue: string
  public color: string
  // @Input('colorchangeform') frm: any;
  @Input('colorslist') colorslist: any;
  @Input('myColor') myColor: string;

  @Output()
  myColorChange = new EventEmitter<string>();
  @Output()
  onClose = new EventEmitter<string>();
  constructor() { }

  ngOnInit(): void {
    this.color = this.myColor;
    this.hue = this.myColor;
  }

  ngAfterViewInit() {
    this.color = this.myColor;
    this.hue = this.myColor;
  }

  onclr(e) {

    // this.zone.run(()=>{
    this.color = this.rgba2hex(e); // for display/output
    // console.log('convert to hex',this.color);
    // var rgb = this.hexToRgb(this.color);
    // console.log('again rgb',rgb);
    this.myColor = this.color;
    this.myColorChange.emit(this.myColor);
    // Do NOT set this.hue = this.color (hex)
    // Keep this.hue as the last RGBA string
    // this.colorchange = this.color;
  }

  rgba2hex(orig) {
    var a: any, isPercent,
      rgb = orig.replace(/\s/g, '').match(/^rgba?\((\d+),(\d+),(\d+),?([^,\s)]+)?/i),
      alpha = (rgb && rgb[4] || "").trim(),
      hex = rgb ?
        (rgb[1] | 1 << 8).toString(16).slice(1) +
        (rgb[2] | 1 << 8).toString(16).slice(1) +
        (rgb[3] | 1 << 8).toString(16).slice(1) : orig;

    if (alpha !== "") {
      a = alpha;
    } else {
      a = 1;
    }
    // multiply before convert to HEX
    a = ((a * 255) | 1 << 8).toString(16).slice(1)
    hex = hex + a;

    return '#' + hex;
  }

  // Helper to convert hex to RGBA string
  hexToRgba(hex: string): string {
    hex = hex.replace('#', '');
    let r = 0, g = 0, b = 0, a = 1;
    if (hex.length === 8) {
      r = parseInt(hex.substring(0, 2), 16);
      g = parseInt(hex.substring(2, 4), 16);
      b = parseInt(hex.substring(4, 6), 16);
      a = parseInt(hex.substring(6, 8), 16) / 255;
    } else if (hex.length === 6) {
      r = parseInt(hex.substring(0, 2), 16);
      g = parseInt(hex.substring(2, 4), 16);
      b = parseInt(hex.substring(4, 6), 16);
    }
    return `rgba(${r},${g},${b},${a})`;
  }

  ngOnDestroy() {
    this.onClose.emit('CLOSE');
  }

  selectClr(cClr) {
    this.color = cClr;
    this.hue = this.hexToRgba(cClr); // convert hex to RGBA for palette
  }

}
